import {button,icon,esc,phraseText,quotedText} from './ui.js';
import {renderTokenBuilder} from './token-builder.js';
import {lessonExplanation} from './lesson-explanation.js';
import {lessonNumberWithVideo} from './video-lesson-state.js';
import {scenarioProgress,scenarioTitle} from './scenario-state.js';
export function renderMessageBuilder(s,top,l,c){
 const p=scenarioProgress(s),x=c.items[p.index],jp=s.courseDirection==='ja-ko',ui=jp?'ja':'ko',lang=jp?'ko':'ja',label=(ko,ja)=>jp?ja:ko;
 const ratio=p.phase==='intro'?0:Math.round((p.index+(p.checked?1:0))/3*100),header=top(`${lessonNumberWithVideo(s,l.number[s.courseDirection])}. ${scenarioTitle(s,l)}`);
 const progress=`<div class="lesson-progress" role="progressbar" aria-label="${label('학습 진행률','学習の進み具合')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${ratio}"><span style="width:${ratio}%"></span></div>`;
 if(p.phase==='intro')return `${header}${progress}<main class="page scenario-page lesson-top" lang="${ui}"><h1>${esc(scenarioTitle(s,l))}</h1><p>${quotedText(c.scene)}</p>${button(label('답장 만들기','返事を作る'),'scenario-next')}</main>`;
 const audio=(part)=>button(icon('sound'),'scenario-audio','icon-button',`data-id="${part}" aria-label="${label('다시 듣기','もう一度聞く')}"`);
 const translation=t=>`<details class="message-meaning"><summary>${label('뜻 보기','意味を見る')}</summary><p lang="${ui}">${quotedText(t)}</p></details>`;
 return `${header}${progress}<main class="page scenario-page message-builder-page" lang="${ui}"><div class="scenario-count">${p.index+1} / 3</div><section class="message-received"><h2>${label('받은 메시지','届いたメッセージ')}</h2><div class="audio-text-row"><p lang="${lang}">${phraseText(x.text,x.phrases||undefined)}</p>${audio('prompt')}</div>${translation(x.meaning)}</section><p class="message-task">${quotedText(x.prompt)}</p><section class="message-reply"><h2>${label('내 답장','自分の返事')}</h2>${p.checked?`<div class="message-finished" role="status"><div class="audio-text-row"><p lang="${lang}">${phraseText(x.answer,jp?undefined:x.parts.flatMap(part=>part.split('|')))}</p>${audio('answer')}</div>${translation(x.answerMeaning)}</div>`:renderTokenBuilder({tokens:x.parts,selected:p.tokens,order:[[2,0,1],[1,2,0],[2,1,0]][p.index],lang,empty:label('말 조각을 순서대로 눌러 주세요.','言葉のパーツを順番に押してください。'),choiceAttributes:i=>`data-action="scenario-token" data-id="${i}"`,selectedAttributes:i=>`data-action="scenario-token" data-id="${i}"`})}${!p.checked&&p.tokens.length?button(label('처음부터','最初から'),'scenario-clear','text-button'):''}</section>${p.retry?`<p class="scenario-feedback" role="status">${label('순서를 다시 확인해 보세요.','順番をもう一度確認しましょう。')} ${quotedText(x.hint)}</p>`:''}${lessonExplanation(x.hint,jp)}<div class="button-pair">${button(label('이전','戻る'),'scenario-previous','secondary')}${p.checked?button(p.index===2?label('학습 마치기','学習を終える'):label('다음','次へ'),'scenario-next'):button(label('확인','確認'),'scenario-check','primary',p.tokens.length===3?'':'disabled')}</div></main>`;
}
